/**
 * Notion Node - Version 1
 * Discriminator: resource=page, operation=get
 */


interface Credentials {
  notionApi: CredentialReference;
}

/** Get a database */
export type NotionV1PageGetParams = {
  resource: 'page';
  operation: 'get';
/**
 * The Page URL from Notion's 'copy link' functionality (or just the ID contained within the URL)
 */
    pageId: string | Expression<string>;
/**
 * Whether to return a simplified version of the response instead of the raw data
 * @builderHint When true, pages under another page or the workspace return only id and name. Database pages return id and simplified properties under their original names and case, such as $json.Status. Rich-text values are strings. People values are arrays of email addresses, with {} for missing emails. When false, read the native properties object. Match expressions and verification output fixtures to the returned page type.
 * @default true
 */
    simple?: boolean | Expression<boolean>;
};

export type NotionV1PageGetOutput = {
  id?: string;
  'Messaggi Schedulati'?: string;
};

export type NotionV1PageGetNode = {
  type: 'n8n-nodes-base.notion';
  version: 1;
  config: NodeConfig<NotionV1PageGetParams> & { credentials?: Credentials };
  output?: Items<NotionV1PageGetOutput>;
};